// ---- Common flags ----

func addCommonFlags(fs *pflag.FlagSet) {
	fs.StringArrayP("filename", "f", nil,
		"Request body from a file (JSON, YAML, or any registered format),\n"+
			"or '-' for stdin. Repeatable; -f files, -i values, and flags\n"+
			"merge in that order.")
	fs.StringArrayP("input", "i", nil,
		"Request body inline (JSON, YAML, or any registered format).\n"+
			"Repeatable; merges after -f files and before flags.")
	fs.StringP("output", "o", "",
		"Output format: json, json-pretty, yaml (or a format registered from main).\n"+
			"Default: pretty on a terminal, compact when piped.")
}

// ---- Request assembly ----

// An InputFormat parses one request-document encoding to JSON.
type InputFormat struct {
	Name  string
	Parse func([]byte) ([]byte, error)
}

// inputFormats is the content-detection order: the first format whose parse
// yields a JSON object claims the input.
var inputFormats = []InputFormat{
	{Name: "json", Parse: func(body []byte) ([]byte, error) {
		if !json.Valid(body) {
			return nil, errors.New("not JSON")
		}
		return body, nil
	}},
	{Name: "yaml", Parse: yaml.YAMLToJSON},
}

// RegisterInputFormat appends a format to the detection order, or replaces
// its namesake. Register before Execute.
func RegisterInputFormat(name string, parse func([]byte) ([]byte, error)) {
	if name == "" || parse == nil {
		panic("RegisterInputFormat: need a format name and a non-nil parser")
	}
	for i, f := range inputFormats {
		if f.Name == name {
			inputFormats[i].Parse = parse
			return
		}
	}
	inputFormats = append(inputFormats, InputFormat{Name: name, Parse: parse})
}

// A Fragment is one request document.
type Fragment struct {
	Source string
	JSON   []byte
}

// LoadInputs returns the request fragments for the -f and -i values in merge
// order: -f documents in argument order ("-" reads stdin), then -i values.
// Content picks each input's format; empty inputs are skipped.
func LoadInputs(files, inline []string, stdin io.Reader) ([]Fragment, error) {
	var out []Fragment
	add := func(source string, raw []byte) error {
		if len(bytes.TrimSpace(raw)) == 0 {
			return nil
		}
		for _, f := range inputFormats {
			body, err := f.Parse(raw)
			if err == nil && bytes.HasPrefix(bytes.TrimSpace(body), []byte("{")) {
				out = append(out, Fragment{Source: source, JSON: body})
				return nil
			}
		}
		formatNames := make([]string, len(inputFormats))
		for i, f := range inputFormats {
			formatNames[i] = f.Name
		}
		return fmt.Errorf("parse %s: not an object in any input format (%s)",
			source, strings.Join(formatNames, ", "))
	}
	for _, name := range files {
		name = strings.TrimSpace(name)
		switch {
		case name == "":
		case name == "-":
			body, err := io.ReadAll(stdin)
			if err != nil {
				return nil, fmt.Errorf("read stdin: %w", err)
			}
			if err := add("stdin", body); err != nil {
				return nil, err
			}
		default:
			body, err := os.ReadFile(name)
			if err != nil {
				return nil, fmt.Errorf("read %s: %w", name, err)
			}
			if err := add(name, body); err != nil {
				return nil, err
			}
		}
	}
	for _, s := range inline {
		if err := add("-i", []byte(s)); err != nil {
			return nil, err
		}
	}
	return out, nil
}

// BuildRequest merges the fragments into req in order. Merging follows
// proto.Merge: populated scalars and oneofs replace, messages merge
// field-wise, repeated fields append, map entries merge per key.
func BuildRequest(req proto.Message, frags []Fragment) error {
	// A fragment is partial by definition; required fields are a property
	// of the assembled request, checked once after the merge.
	for _, frag := range frags {
		next := req.ProtoReflect().New().Interface()
		if err := (protojson.UnmarshalOptions{AllowPartial: true}).Unmarshal(frag.JSON, next); err != nil {
			return fmt.Errorf("decode %s: %w", frag.Source, err)
		}
		proto.Merge(req, next)
	}
	if err := proto.CheckInitialized(req); err != nil {
		return fmt.Errorf("request: %w", err)
	}
	return nil
}

// ---- Output ----

// A Formatter writes JSON records to w.
type Formatter interface {
	Format(w io.Writer, r Records) error
}

// Records yields JSON records one at a time. Next returns io.EOF at the end.
type Records struct {
	Next func() ([]byte, error)
}

// messageRecords wraps m as a one-record stream.
func messageRecords(m proto.Message) Records {
	done := false
	return Records{Next: func() ([]byte, error) {
		if done {
			return nil, io.EOF
		}
		done = true
		return marshalJSON(m)
	}}
}

// JSONFormat writes each record as a line of JSON. Indent pretty-prints.
type JSONFormat struct{ Indent bool }

func (j JSONFormat) Format(w io.Writer, r Records) error {
	for {
		rec, err := r.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		if j.Indent {
			var buf bytes.Buffer
			if err := json.Indent(&buf, rec, "", "  "); err != nil {
				return err
			}
			rec = buf.Bytes()
		}
		if _, err := fmt.Fprintln(w, string(rec)); err != nil {
			return err
		}
	}
}

// YAMLFormat writes each record as a YAML document, separated by "---".
type YAMLFormat struct{}

func (YAMLFormat) Format(w io.Writer, r Records) error {
	first := true
	for {
		rec, err := r.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		if !first {
			if _, err := io.WriteString(w, "---\n"); err != nil {
				return err
			}
		}
		first = false
		doc, err := yaml.JSONToYAML(rec)
		if err != nil {
			return err
		}
		if _, err := w.Write(doc); err != nil {
			return err
		}
	}
}

// formatters holds the built-in formats by name.
var formatters = map[string]Formatter{
	"json":        JSONFormat{},
	"json-pretty": JSONFormat{Indent: true},
	"yaml":        YAMLFormat{},
}

// defaultFormat is the format used when -o is empty.
var defaultFormat string

// RegisterFormat adds or replaces the format named name. Call before Execute.
func RegisterFormat(name string, f Formatter) {
	if name == "" || f == nil {
		panic("RegisterFormat: need a format name and a non-nil Formatter")
	}
	formatters[name] = f
}

// UnregisterFormat removes the format named name. Call before Execute.
func UnregisterFormat(name string) {
	delete(formatters, name)
}

// SetDefaultFormat sets the format used when -o is empty. Call before Execute.
func SetDefaultFormat(name string) {
	defaultFormat = name
}

// render writes r to the command's output using the -o format.
func render(cmd *cobra.Command, r Records) error {
	format, err := cmd.Flags().GetString("output")
	if err != nil {
		return err
	}
	out := cmd.OutOrStdout()
	f, err := lookupFormat(format, out)
	if err != nil {
		return err
	}
	return f.Format(out, r)
}

// lookupFormat returns the Formatter for an -o value. Empty uses the default
// format; with no default, JSON is used: pretty on a terminal, compact otherwise.
func lookupFormat(format string, w io.Writer) (Formatter, error) {
	if format == "" {
		if defaultFormat == "" {
			pretty := false
			if f, ok := w.(*os.File); ok {
				pretty = term.IsTerminal(int(f.Fd()))
			}
			return JSONFormat{Indent: pretty}, nil
		}
		format = defaultFormat
	}
	f, ok := formatters[format]
	if !ok {
		names := make([]string, 0, len(formatters))
		for name := range formatters {
			names = append(names, name)
		}
		slices.Sort(names)
		return nil, fmt.Errorf("unknown output format %q; use one of: %s",
			format, strings.Join(names, ", "))
	}
	return f, nil
}

// marshalJSON returns m as compact JSON. json.Compact makes protojson's
// deliberately unstable spacing reproducible.
func marshalJSON(m proto.Message) ([]byte, error) {
	raw, err := protojson.Marshal(m)
	if err != nil {
		return nil, err
	}
	var buf bytes.Buffer
	if err := json.Compact(&buf, raw); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}
